(()=>{const q=id=>document.getElementById(id);function show(){const c=q('identityCase').value,close=q('identityFocus').value==='joint';for(const [id,name] of [['identityBefore','before'],['identityBaseline','baseline'],['identityAgent','agent']]){const im=q(id);im.src=`assets/identity/${name}-${c}.png`;im.alt=`${c} 사례 · ${name==='before'?'공통 수정 입력':name==='baseline'?'일반 수정':'구조화 수정'}`;im.parentElement.classList.toggle('zoom',close);im.style.objectPosition=c==='D'?'44% 70%':'50% 50%';im.style.transform=close&&c==='D'?'scale(1.6)':'none';im.parentElement.style.aspectRatio=close&&c==='C'?'3 / 1':'4 / 3';}q('identityVerdict').textContent=c==='D'?'당시 사용자 관찰: 양쪽 모두 촉 길이가 과하고, 두 결과의 차이를 느끼기 어려움. 길이 과장을 허용할 가능성은 언급됐지만 통과 확정은 없었습니다.':'당시 사용자 관찰: 양쪽 모두 촉이 휘어 심각한 결함으로 실패. 연결부는 개선됐지만 원래 제품으로 복구됐다고 볼 수 없었습니다.';}q('identityCase').onchange=show;q('identityFocus').onchange=show;show();})();